def can_chain(dominoes):
    """Return a cyclic chain using each domino exactly once, or None.

    A valid chain has matching halves between adjacent stones, and the
    left end of the first stone matches the right end of the last stone.
    """
    if not dominoes:
        return []

    for start in range(len(dominoes)):
        chain = [dominoes[start]]
        remaining = dominoes[:start] + dominoes[start + 1:]
        result = _chain_rest(chain, remaining)
        if result is not None:
            return result
    return None


def _chain_rest(chain, remaining):
    if not remaining:
        if chain[0][0] == chain[-1][1]:
            return chain
        return None

    end = chain[-1][1]
    for i, domino in enumerate(remaining):
        rest = remaining[:i] + remaining[i + 1:]
        if domino[0] == end:
            result = _chain_rest(chain + [domino], rest)
            if result is not None:
                return result
        if domino[1] == end and domino[0] != domino[1]:
            result = _chain_rest(chain + [domino[::-1]], rest)
            if result is not None:
                return result
    return None

